$titulo_pagina='Meu Feed e Anúncios';$estilos_pagina=['/assets/css/admin.css?v=5','/assets/css/creator-dashboard.css?v=1'];require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/functions.php';verificarProfissional();$perfil=pegar_perfil_profissional_por_usuario($_SESSION['usuario_id']);if(!$perfil)redirecionar('/dashboard/profissional.php');$erros=[];
function salvar_imagem_conteudo($arquivo,$pasta,&$erros){if(empty($arquivo['name']))return '';$mime=(new finfo(FILEINFO_MIME_TYPE))->file($arquivo['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($ext[$mime])){$erros[]='Envie apenas JPG, PNG ou WebP.';return '';}$dir=__DIR__.'/../assets/uploads/'.$pasta;if(!is_dir($dir))mkdir($dir,0755,true);$nome=bin2hex(random_bytes(16)).'.'.$ext[$mime];return move_uploaded_file($arquivo['tmp_name'],$dir.'/'.$nome)?'/assets/uploads/'.$pasta.'/'.$nome:'';}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!validar_csrf($_POST['csrf_token']??''))$erros[]='A sessão expirou.';$acao=$_POST['acao']??'';$id=(int)($_POST['id']??0);
 if(!$erros&&$acao==='publicar'){$texto=trim($_POST['conteudo']??'');$imagem=trim($_POST['imagem_url']??'');$upload=salvar_imagem_conteudo($_FILES['imagem']??[],'posts',$erros);if($upload)$imagem=$upload;$tags=implode(' ',array_slice(array_filter(array_map(fn($t)=>'#'.preg_replace('/[^\pL\pN_]/u','',ltrim($t,'#')),preg_split('/[,\s]+/',$_POST['tags']??''))),0,10));if(mb_strlen($texto)<3)$erros[]='Escreva uma publicação.';if(!$erros){$stmt=$mysqli->prepare('INSERT INTO publicacoes_profissionais(profissional_id,conteudo,imagem_url,tags) VALUES(?,?,?,?)');$stmt->bind_param('isss',$perfil['id'],$texto,$imagem,$tags);$stmt->execute();mensagem_sucesso('Publicação enviada ao feed.');redirecionar('/dashboard/conteudo.php');}}
 if(!$erros&&$acao==='editar'){$texto=trim($_POST['conteudo']??'');$tags=trim($_POST['tags']??'');$stmt=$mysqli->prepare('UPDATE publicacoes_profissionais SET conteudo=?,tags=? WHERE id=? AND profissional_id=?');$stmt->bind_param('ssii',$texto,$tags,$id,$perfil['id']);$stmt->execute();mensagem_sucesso('Publicação atualizada.');redirecionar('/dashboard/conteudo.php');}
 if(!$erros&&$acao==='excluir'){$stmt=$mysqli->prepare('DELETE FROM publicacoes_profissionais WHERE id=? AND profissional_id=?');$stmt->bind_param('ii',$id,$perfil['id']);$stmt->execute();mensagem_sucesso('Publicação apagada.');redirecionar('/dashboard/conteudo.php');}
 if(!$erros&&$acao==='responder'){$comentario=trim($_POST['comentario']??'');$publicacao=(int)($_POST['publicacao_id']??0);$stmt=$mysqli->prepare('SELECT id FROM publicacoes_profissionais WHERE id=? AND profissional_id=?');$stmt->bind_param('ii',$publicacao,$perfil['id']);$stmt->execute();if($comentario&&$stmt->get_result()->fetch_row()){$stmt=$mysqli->prepare('INSERT INTO comentarios_publicacoes(publicacao_id,usuario_id,comentario) VALUES(?,?,?)');$stmt->bind_param('iis',$publicacao,$_SESSION['usuario_id'],$comentario);$stmt->execute();}redirecionar('/dashboard/conteudo.php');}
 if(!$erros&&$acao==='anuncio'){$titulo=trim($_POST['titulo']??'');$texto=trim($_POST['texto']??'');$link=trim($_POST['link_url']??'');$imagem=salvar_imagem_conteudo($_FILES['imagem_anuncio']??[],'ads',$erros);if(mb_strlen($titulo)<3)$erros[]='Informe o título do anúncio.';if(!$erros){$stmt=$mysqli->prepare('INSERT INTO anuncios_profissionais(profissional_id,titulo,texto,imagem_url,link_url,status) VALUES(?,?,?,?,?,\'aprovado\')');$stmt->bind_param('issss',$perfil['id'],$titulo,$texto,$imagem,$link);$stmt->execute();$id_anuncio=$mysqli->insert_id;$codigo='VXAD-'.str_pad((string)$id_anuncio,8,'0',STR_PAD_LEFT);$stmt=$mysqli->prepare('UPDATE anuncios_profissionais SET codigo=? WHERE id=?');$stmt->bind_param('si',$codigo,$id_anuncio);$stmt->execute();mensagem_sucesso('Anúncio publicado gratuitamente. Código: '.$codigo);redirecionar('/dashboard/conteudo.php');}}
}
$stmt=$mysqli->prepare('SELECT pub.*,(SELECT COUNT(*) FROM curtidas_publicacoes c WHERE c.publicacao_id=pub.id) curtidas FROM publicacoes_profissionais pub WHERE profissional_id=? ORDER BY criado_em DESC');$stmt->bind_param('i',$perfil['id']);$stmt->execute();$posts=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt=$mysqli->prepare('SELECT * FROM anuncios_profissionais WHERE profissional_id=? ORDER BY criado_em DESC');$stmt->bind_param('i',$perfil['id']);$stmt->execute();$ads=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);require_once __DIR__.'/../includes/header.php';?>
<div class="container creator-page"><div class="page-heading"><div><h1>Meu Feed</h1><p>Gerencie sua presença pública, interações e anúncios.</p></div><a class="btn btn-secondary" href="/profissional.php?id=<?php echo (int)$perfil['id']; ?>">Ver perfil público</a></div><?php exibir_mensagens(); ?><?php if($erros): ?><div class="alerta alerta-erro"><?php echo sanitizar(implode(' ',$erros)); ?></div><?php endif; ?><nav class="creator-tabs"><a href="#publicar">Nova publicação</a><a href="#publicacoes">Minhas publicações</a><a href="#anuncios">Anúncios</a></nav>
<section id="publicar" class="creator-panel"><h2>Criar publicação</h2><form method="POST" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><input type="hidden" name="acao" value="publicar"><div class="form-group"><label>Conteúdo</label><textarea name="conteudo" rows="5" required></textarea></div><div class="creator-grid"><div class="form-group"><label>Foto do computador</label><input type="file" name="imagem" accept="image/jpeg,image/png,image/webp"></div><div class="form-group"><label>Ou URL da imagem</label><input type="url" name="imagem_url"></div></div><div class="form-group"><label>Tags</label><input name="tags" placeholder="#eletrica #dicas"></div><button class="btn">Publicar</button></form></section>
<section id="publicacoes"><h2>Minhas publicações</h2><div class="creator-posts"><?php foreach($posts as $post): ?><article><?php if($post['imagem_url']): ?><img src="<?php echo sanitizar($post['imagem_url']); ?>" alt="Publicação"><?php endif; ?><form method="POST"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><input type="hidden" name="acao" value="editar"><input type="hidden" name="id" value="<?php echo (int)$post['id']; ?>"><textarea name="conteudo" rows="4"><?php echo sanitizar($post['conteudo']); ?></textarea><input name="tags" value="<?php echo sanitizar($post['tags']); ?>"><button class="btn-small">Salvar edição</button></form><div class="creator-meta">♥ <?php echo (int)$post['curtidas']; ?> curtidas</div><?php $stmt=$mysqli->prepare('SELECT c.*,u.nome FROM comentarios_publicacoes c JOIN usuarios u ON u.id=c.usuario_id WHERE c.publicacao_id=? ORDER BY c.id');$stmt->bind_param('i',$post['id']);$stmt->execute();foreach($stmt->get_result()->fetch_all(MYSQLI_ASSOC) as $comment): ?><p class="creator-comment"><strong><?php echo sanitizar($comment['nome']); ?>:</strong> <?php echo sanitizar($comment['comentario']); ?></p><?php endforeach; ?><form class="reply-form" method="POST"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><input type="hidden" name="acao" value="responder"><input type="hidden" name="publicacao_id" value="<?php echo (int)$post['id']; ?>"><input name="comentario" placeholder="Responder aos comentários"><button>Responder</button></form><form method="POST" onsubmit="return confirm('Apagar esta publicação?')"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><input type="hidden" name="acao" value="excluir"><input type="hidden" name="id" value="<?php echo (int)$post['id']; ?>"><button class="btn-small btn-danger">Apagar</button></form></article><?php endforeach; ?></div></section>
<section id="anuncios" class="creator-panel"><h2>Gerenciar anúncios</h2><p>Envie sua campanha. Ela será exibida somente depois da aprovação administrativa.</p><form method="POST" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?php echo token_csrf(); ?>"><input type="hidden" name="acao" value="anuncio"><div class="creator-grid"><div class="form-group"><label>Título</label><input name="titulo" required></div><div class="form-group"><label>Link de destino</label><input name="link_url" type="url"></div></div><div class="form-group"><label>Texto</label><textarea name="texto" rows="3"></textarea></div><div class="form-group"><label>Imagem</label><input type="file" name="imagem_anuncio" accept="image/jpeg,image/png,image/webp"></div><button class="btn">Enviar para aprovação</button></form><div class="ad-list"><?php foreach($ads as $ad): ?><article><strong><?php echo sanitizar($ad['titulo']); ?></strong><span class="status status-<?php echo $ad['status']==='aprovado'?'confirmado':'pendente'; ?>"><?php echo sanitizar($ad['status']); ?></span></article><?php endforeach; ?></div></section></div><?php require_once __DIR__.'/../includes/footer.php'; ?>
